window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cf428812a4d3b3d6"]={"versions": [{"id": "FIG-cf428812a4d3b3d6", "releases": ["R4.0.3", "R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dokumenten-Abhängigkeitsdiagramm (Informations-/Architekturübersicht) zur Einordnung des Berichts <code>Specification Interoperability of AUTOSAR Tools</code> innerhalb der AUTOSAR-Spezifikationslandschaft. Das Diagramm ordnet die Spezifikationsdokumente in einer dreistufigen Hierarchie an und verdeutlicht die methodischen und metamodellbezogenen Abhängigkeiten sowie Ergänzungsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst fünf Dokumentenentitäten (dargestellt als rechteckige Blöcke mit Farbcodierung):</p>\n<ul class=\"fig-list\"><li>Zentrales Dokument: <code>Specification Interoperability of AUTOSAR Tools</code> (rot hinterlegt).\n</li><li>Vorgelagerte / übergeordnete Dokumente (obere Ebene):\n<ul class=\"fig-list\"><li><code>Requirements on Interoperability of AUTOSAR Tools</code> (rot hinterlegt).\n</li><li><code>Methodology</code> (gelb hinterlegt).\n</li></ul>\n</li><li>Nachgelagerte / ergänzte Dokumente (untere Ebene):\n<ul class=\"fig-list\"><li><code>Model Persistence Rules for XML</code> (blau hinterlegt).\n</li><li><code>Generic Structure Template</code> (blau hinterlegt).\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen / Kanten:</p>\n<ul class=\"fig-list\"><li>Von <code>Specification Interoperability of AUTOSAR Tools</code> führen gestrichelte Pfeile nach oben zu <code>Requirements on Interoperability of AUTOSAR Tools</code> und <code>Methodology</code>, jeweils annotiert mit dem Stereotyp bzw. der Beziehungsbezeichnung <code>depends on</code>.\n</li><li>Von <code>Specification Interoperability of AUTOSAR Tools</code> führen gestrichelte Pfeile nach unten zu <code>Model Persistence Rules for XML</code> und <code>Generic Structure Template</code>, jeweils annotiert mit <code>supplements</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dokumentenabhängigkeiten ohne Laufzeitdynamik. Die Pfeilrichtungen spezifizieren Referenzierungs- und Ergänzungsbeziehungen: Das zentrale Dokument baut auf den Anforderungen (<code>Requirements on Interoperability of AUTOSAR Tools</code>) und dem methodischen Rahmen (<code>Methodology</code>) auf (<code>depends on</code>) und konkretisiert bzw. ergänzt die metamodell- und persistenzbezogenen Spezifikationen (<code>Model Persistence Rules for XML</code>, <code>Generic Structure Template</code>) auf M1- und Implementierungsebene (<code>supplements</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Werkzeugentwickler und Spezifikationsanwender legt das Diagramm die normative Lesereihenfolge und Bindung fest: Implementierungen der AUTOSAR-Werkzeuginteroperabilität müssen die übergeordneten Anforderungen und die AUTOSAR-Methodik beachten und harmonieren mit den Festlegungen des <code>Generic Structure Template</code> sowie den XML-Persistenzregeln (<code>Model Persistence Rules for XML</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-793d9617bb864a4e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dokumenten-Abhängigkeitsdiagramm (Informations-/Architekturübersicht) zur Einordnung des Berichts <code>Specification Interoperability of AUTOSAR Tools</code> innerhalb der AUTOSAR-Spezifikationslandschaft. Das Diagramm ordnet die Spezifikationsdokumente in einer dreistufigen Hierarchie an und verdeutlicht die methodischen und metamodellbezogenen Abhängigkeiten sowie Ergänzungsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst sechs Dokumentenentitäten (dargestellt als rechteckige Blöcke mit Farbcodierung):</p>\n<ul class=\"fig-list\"><li>Zentrales Dokument: <code>Specification Interoperability of AUTOSAR Tools</code> (hellblau/graublau hinterlegt).\n</li><li>Vorgelagerte / übergeordnete Dokumente (obere Ebene):\n<ul class=\"fig-list\"><li><code>Requirements on Interoperability of AUTOSAR Tools</code> (hellblau/graublau hinterlegt).\n</li><li><code>Methodology</code> (pfirsich-/orangefarben hinterlegt).\n</li></ul>\n</li><li>Nachgelagerte / ergänzte Dokumente (untere Ebene, drei Blöcke petrolblau hinterlegt):\n<ul class=\"fig-list\"><li><code>XML Schema Production Rules</code>\n</li><li><code>ARXML Serialization Rules</code>\n</li><li><code>Generic Structure Template</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen / Kanten:</p>\n<ul class=\"fig-list\"><li>Von <code>Specification Interoperability of AUTOSAR Tools</code> führen gestrichelte Pfeile nach oben zu <code>Requirements on Interoperability of AUTOSAR Tools</code> und <code>Methodology</code>, jeweils annotiert mit <code>depends on</code>.\n</li><li>Von <code>Specification Interoperability of AUTOSAR Tools</code> führen drei gestrichelte Pfeile nach unten zu <code>XML Schema Production Rules</code>, <code>ARXML Serialization Rules</code> und <code>Generic Structure Template</code>, jeweils annotiert mit <code>supplements</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Dokumentenabhängigkeiten ohne Laufzeitdynamik. Die Pfeilrichtungen spezifizieren Referenzierungs- und Ergänzungsbeziehungen: Das zentrale Dokument stützt sich auf die übergeordneten Anforderungen und die AUTOSAR-Methodik (<code>depends on</code>) und ergänzt die Dokumente <code>XML Schema Production Rules</code>, <code>ARXML Serialization Rules</code> sowie <code>Generic Structure Template</code> hinsichtlich der interoperablen Werkzeugnutzung (<code>supplements</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Werkzeugentwickler und Spezifikationsanwender definiert das Schaubild den verbindlichen Dokumentenkontext: Interoperable Werkzeuge müssen neben den methodischen Vorgaben und Tool-Requirements explizit die Schema-Generierungsregeln (<code>XML Schema Production Rules</code>), die Serialisierungsregeln für ARXML (<code>ARXML Serialization Rules</code>) sowie das Metamodell-Fundament des <code>Generic Structure Template</code> berücksichtigen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-cf428812a4d3b3d6", "to": "FIG-793d9617bb864a4e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Das Dokument <code>Model Persistence Rules for XML</code> entfällt.\n</li><li>Die Dokumente <code>XML Schema Production Rules</code> und <code>ARXML Serialization Rules</code> wurden neu ergänzt; <code>Specification Interoperability of AUTOSAR Tools</code> besitzt jeweils eine gestrichelte gerichtete Beziehung mit der Beschriftung <code>supplements</code> auf beide Dokumente.\n</li><li>Das Farbschema der Spezifikationsblöcke wurde von gesättigtem Rot/Gelb/Blau auf gedeckte Pastell-/Petrol-Farbtöne (Hellblau, Pfirsich/Orange, Petrolblau) umgestellt.\n</li></ul>"}]};
